func (this *Combo) DeprocessText(text *win32.TCHAR, start int32, end int32, terminate bool) *win32.TCHAR {
	if text == (nil) || this.segments == (nil) {
		return text
	}
	var length int32 = text.Length()
	if length == 0 {
		return text
	}
	var nSegments int32 = int32(len(this.segments))
	if nSegments == 0 {
		return text
	}
	var chars []uint16
	if start < 0 {
		start = 0
	}
	chars = text.Chars
	if int32(text.Chars[length-1]) == 0 {
		length--
	}
	if end == -1 {
		end = length
	}
	if end > this.segments[0] && start <= this.segments[nSegments-1] {
		var nLeadSegments int32 = 0
		for start-nLeadSegments > this.segments[nLeadSegments] {
			nLeadSegments++
		}
		var segmentCount int32 = nLeadSegments
		for i := int32(start); i < end; i++ {
			if segmentCount < nSegments && i-segmentCount == this.segments[segmentCount] {
				segmentCount++
			} else {
				chars[i-segmentCount+nLeadSegments] = chars[i]
			}
		}
		length = end - start - segmentCount + nLeadSegments
	}
	if start != 0 || end != length {
		var newChars []uint16 = make([]uint16, length)
		copy(newChars[0:], chars[start:start+length])
		return win32.NewTCHARCharsTerminate(newChars, terminate)
	}
	return text
}

