func (this *Combo) GetSegmentsText(text string, eventLike EventLike) string {
	var event *Event
	if eventLike != nil {
		event = eventLike.AsEvent()
	}
	_ = event
	if text == "" || event == (nil) {
		return text
	}
	var segments []int32 = event.Segments
	if segments == (nil) {
		return text
	}
	var nSegments int32 = int32(len(segments))
	if nSegments == 0 {
		return text
	}
	var segmentsChars []uint16 = event.SegmentsChars
	var length int32 = jrt.StringLength(text)
	var oldChars []uint16 = make([]uint16, length)
	jrt.GetChars(text, 0, length, oldChars, 0)
	var newChars []uint16 = make([]uint16, length+nSegments)
	var charCount int32 = 0
	var segmentCount int32 = 0
	var defaultSeparator uint16
	if this.impl.getOrientation_() == RIGHT_TO_LEFT {
		defaultSeparator = ComboRTL_MARK
	} else {
		defaultSeparator = ComboLTR_MARK
	}
	for charCount < length {
		if segmentCount < nSegments && charCount == segments[segmentCount] {
			var separator uint16
			if segmentsChars != (nil) && int32(len(segmentsChars)) > segmentCount {
				separator = segmentsChars[segmentCount]
			} else {
				separator = defaultSeparator
			}
			t711 := segmentCount
			segmentCount++
			newChars[charCount+t711] = separator
		} else {
			idx713 := charCount + segmentCount
			t712 := charCount
			charCount++
			newChars[idx713] = oldChars[t712]
		}
	}
	for segmentCount < nSegments {
		segments[segmentCount] = charCount
		var separator uint16
		if segmentsChars != (nil) && int32(len(segmentsChars)) > segmentCount {
			separator = segmentsChars[segmentCount]
		} else {
			separator = defaultSeparator
		}
		t714 := segmentCount
		segmentCount++
		newChars[charCount+t714] = separator
	}
	return string(utf16.Decode(newChars[0 : 0+int32(len(newChars))]))
}

