func (this *Combo) sendKeyEventTypeMsgWParamLParamEvent_(type_ int32, msg int32, wParam int64, lParam int64, event *Event) bool {
	if !this.Composite.sendKeyEventTypeMsgWParamLParamEvent_(type_, msg, wParam, lParam, event) {
		return false
	}
	if (this.style & READ_ONLY) != 0 {
		return true
	}
	if type_ != KeyDown {
		return true
	}
	if msg != win32.OSWM_CHAR && msg != win32.OSWM_KEYDOWN && msg != win32.OSWM_IME_CHAR {
		return true
	}
	if int32(event.Character) == 0 {
		return true
	}
	if !this.Hooks(Verify) && !this.Filters(Verify) {
		return true
	}
	var key uint16 = event.Character
	var stateMask int32 = event.StateMask
	switch msg {
	case win32.OSWM_CHAR:
		if int32(key) != 0x08 && int32(key) != 0x7F && int32(key) != int32('\u000d') && int32(key) != int32('\u0009') && int32(key) != int32('\u000a') {
			break
		}
		fallthrough
	case win32.OSWM_KEYDOWN:
		if (stateMask & (ALT | SHIFT | CONTROL)) != 0 {
			return false
		}
		break
	}
	if int32(win32.OSGetKeyState(win32.OSVK_LBUTTON)) < 0 {
		if win32.OSGetDlgItem(this.Handle, ComboCBID_EDIT) == win32.OSGetCapture() {
			return true
		}
	}
	var oldText string = ""
	var start []int32 = make([]int32, 1)
	var end []int32 = make([]int32, 1)
	var hwndText int64 = win32.OSGetDlgItem(this.Handle, ComboCBID_EDIT)
	if hwndText == 0 {
		return true
	}
	win32.OSSendMessageOverload1(hwndText, win32.OSEM_GETSEL, start, end)
	switch key {
	case uint16(0x08):
		if start[0] == end[0] {
			if start[0] == 0 {
				return true
			}
			start[0] = start[0] - 1
			start[0] = int32(math.Max(float64(start[0]), float64(0)))
		}
		break
	case uint16(0x7F):
		if start[0] == end[0] {
			var length int32 = win32.OSGetWindowTextLength(hwndText)
			if start[0] == length {
				return true
			}
			end[0] = end[0] + 1
			end[0] = int32(math.Min(float64(end[0]), float64(length)))
		}
		break
	case '\u000d':
		return true
	default:
		if int32(key) != int32('\u0009') && int32(key) < 0x20 {
			return true
		}
		oldText = string(utf16.Decode([]uint16{key}))
		break
	}
	var newText string = this.VerifyText(oldText, start[0], end[0], event)
	if newText == "" {
		return false
	}
	if newText == oldText {
		return true
	}
	var buffer *win32.TCHAR = win32.NewTCHARStringTerminate(newText, true)
	win32.OSSendMessageOverload4(hwndText, win32.OSEM_SETSEL, int64(start[0]), int64(end[0]))
	win32.OSSendMessage(hwndText, win32.OSEM_REPLACESEL, int64(0), buffer)
	return false
}

