func (this *Combo) updateOrientation_() {
	var bits int32 = win32.OSGetWindowLong(this.Handle, win32.OSGWL_EXSTYLE)
	if (this.style & RIGHT_TO_LEFT) != 0 {
		bits |= win32.OSWS_EX_LAYOUTRTL
	} else {
		bits &= ^win32.OSWS_EX_LAYOUTRTL
	}
	bits &= ^win32.OSWS_EX_RTLREADING
	win32.OSSetWindowLong(this.Handle, win32.OSGWL_EXSTYLE, bits)
	var hwndText int64 = int64(0)
	var hwndList int64 = int64(0)
	var pcbi *win32.COMBOBOXINFO = win32.NewCOMBOBOXINFO()
	pcbi.CbSize = win32.COMBOBOXINFOSizeof
	if win32.OSGetComboBoxInfo(this.Handle, pcbi) {
		hwndText = pcbi.HwndItem
		hwndList = pcbi.HwndList
	}
	if hwndText != 0 {
		var bits1 int32 = win32.OSGetWindowLong(hwndText, win32.OSGWL_EXSTYLE)
		var bits2 int32 = win32.OSGetWindowLong(hwndText, win32.OSGWL_STYLE)
		if (this.style & RIGHT_TO_LEFT) != 0 {
			bits1 |= win32.OSWS_EX_RIGHT | win32.OSWS_EX_RTLREADING
			bits2 |= win32.OSES_RIGHT
		} else {
			bits1 &= ^(win32.OSWS_EX_RIGHT | win32.OSWS_EX_RTLREADING)
			bits2 &= ^win32.OSES_RIGHT
		}
		win32.OSSetWindowLong(hwndText, win32.OSGWL_EXSTYLE, bits1)
		win32.OSSetWindowLong(hwndText, win32.OSGWL_STYLE, bits2)
		var rect *win32.RECT = win32.NewRECT()
		win32.OSGetWindowRect(hwndText, rect)
		var width int32 = rect.Right - rect.Left
		var height int32 = rect.Bottom - rect.Top
		win32.OSGetWindowRect(this.Handle, rect)
		var widthCombo int32 = rect.Right - rect.Left
		var heightCombo int32 = rect.Bottom - rect.Top
		var uFlags int32 = win32.OSSWP_NOMOVE | win32.OSSWP_NOZORDER | win32.OSSWP_NOACTIVATE
		win32.OSSetWindowPos(hwndText, int64(0), 0, 0, width-1, height-1, uFlags)
		win32.OSSetWindowPos(this.Handle, int64(0), 0, 0, widthCombo-1, heightCombo-1, uFlags)
		win32.OSSetWindowPos(hwndText, int64(0), 0, 0, width, height, uFlags)
		win32.OSSetWindowPos(this.Handle, int64(0), 0, 0, widthCombo, heightCombo, uFlags)
		win32.OSInvalidateRect(this.Handle, nil, true)
	}
	if hwndList != 0 {
		var bits1 int32 = win32.OSGetWindowLong(hwndList, win32.OSGWL_EXSTYLE)
		if (this.style & RIGHT_TO_LEFT) != 0 {
			bits1 |= win32.OSWS_EX_LAYOUTRTL
		} else {
			bits1 &= ^win32.OSWS_EX_LAYOUTRTL
		}
		win32.OSSetWindowLong(hwndList, win32.OSGWL_EXSTYLE, bits1)
	}
}

