func ComboCheckStyle(style int32) int32 {
	style &= ^BORDER
	style &= ^(H_SCROLL | V_SCROLL)
	style = WidgetCheckBits(style, DROP_DOWN, SIMPLE, 0, 0, 0, 0)
	if (style & SIMPLE) != 0 {
		return style & ^READ_ONLY
	}
	return style
}

func upcastComboToControl(x *Combo) *Control {
	if x == nil {
		return nil
	}
	return &x.Control
}

